import {$,$$,esc,icon,common,summary,modal,toast,load,save,sampleInfo} from './prototype-shared.js?v=345e8a902fcf721a';
import '../custom-controls.js?v=345e8a902fcf721a';
import {getDocument,documentInfo,updateDocument} from './document-store.js?v=345e8a902fcf721a';
common();
const documentId=new URLSearchParams(location.search).get('document');
const linkedDocument=getDocument(documentId);
const infoKey=linkedDocument?'info:'+documentId:'info',questionsKey=linkedDocument?'questions:'+documentId:'questions';
let info=load(infoKey,linkedDocument?documentInfo(linkedDocument):sampleInfo);
if(linkedDocument)$('#back-info').href='./coverletter-info.html?document='+encodeURIComponent(documentId);
const sampleAnswer='저는 사용자의 작은 불편을 발견하고, 이를 더 나은 경험으로 바꾸는 프로덕트 디자이너가 되고 싶습니다.\n\n팀 프로젝트에서 취업 준비생의 정보 탐색 과정을 조사했습니다. 인터뷰와 사용성 테스트를 통해 정보가 부족해서가 아니라, 나에게 필요한 정보를 선택하기 어려워 다음 행동으로 이어지지 않는다는 문제를 발견했습니다. 저는 핵심 과업을 정리하고 화면의 정보 구조와 안내 문구를 개선했습니다.\n\n이 경험을 바탕으로 사용자의 목소리를 구체적인 디자인 결정으로 연결하고 싶습니다. 다양한 직무의 동료와 함께 가설을 검증하며, 누구나 자신의 가능성을 발견할 수 있는 서비스를 만들어 가겠습니다.';
const seed=[{uid:0,type:'지원 동기',question:'지원 동기와 해당 직무를 위해 준비한 경험을 서술해 주세요.',mode:'GPT Pro',prompt:'취업 준비생 대상 사용자 인터뷰, 정보 탐색 과정 개선, 팀 프로젝트에서 프로토타입 제작과 사용성 테스트를 담당한 경험',body:sampleAnswer,language:'한국어',original:null}];
let questions=load(questionsKey,seed),sequence=Math.max(0,...questions.map(q=>q.uid))+1;
const categories=['자유 형식','성장과정','성격의 장·단점','지원 동기','입사 후 포부','가치관','강점','직무관련 경력/경험','기업 이해 및 분석','목표달성','기업 인재상','의사소통 능력','문제해결','자기 개발 계획','조직 적응 능력','직무 역량 수준','직업 윤리 의식','팀 워크','리더쉽','기타','Cover letter'];
const models=[['직접쓰기','directly'],['ChatGPT','chat_gpt'],['GPT Pro','chat_gpt-4o'],['PenGPT','deep_gpt']];
const blank=()=>({uid:sequence++,type:'',question:'',mode:'직접쓰기',prompt:'',body:'',language:'한국어',original:null});
function persist(){save(questionsKey,questions);save(infoKey,info);if(linkedDocument)updateDocument(documentId,{title:info.title,job:info.job,industry:info.ind,companyType:info.cor,company:info.com});}
function form(q,index){return `<form id="form${q.uid}" name="form" class="question-form" data-uid="${q.uid}"><div id="css${q.uid}" name="css" class="question-card form-control"><div class="question-heading"><h2><span class="question-number">${String(index+1).padStart(2,'0')}</span> 문항 ${index+1}</h2><span>자기소개서</span></div><div class="question-inputs d-flex"><div id="free_id_${q.uid}"><select id="q_select${q.uid}" name="keyword_input${q.uid}" aria-label="문항 ${index+1} 카테고리" data-q-field="type"><option value="">질문 카테고리</option>${categories.map(c=>`<option ${q.type===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div id="free_id_text_${q.uid}"><input id="q_input${q.uid}" name="q_input" data-q-field="question" aria-label="문항 ${index+1} 질문" placeholder="자기소개서 질문을 입력해 주세요." value="${esc(q.question)}"></div></div><hr><div class="form-group"><div class="gpt_choose_wrap" id="gpt_choose_wrap${q.uid}"><p>이용하실 AI를 골라주세요.</p><div class="gpt_choose" role="group" aria-label="문항 ${index+1} 작성 방식">${models.map(([label,name])=>`<button type="button" class="gpt_choose_btn btn ${q.mode===label?'active':''}" name="${name}" data-mode="${label}" aria-pressed="${q.mode===label}">${label}</button>`).join('')}</div></div><div class="ai-input" name="keyword_input_gpt_${q.uid}" ${q.mode==='직접쓰기'?'hidden':''}><label for="keyword_input${q.uid}">${icon('Sparkles')} 나의 경험과 키워드</label><textarea id="keyword_input${q.uid}" name="keyword_input_gpt_${q.uid}" data-q-field="prompt" maxlength="500" placeholder="어떤 경험을 했나요? 나의 역할과 결과를 구체적으로 입력해 주세요.">${esc(q.prompt)}</textarea><div class="ai-input-bottom"><span>AI에게 키워드나 문장을 입력해 주세요 · <span data-prompt-count>${q.prompt.length}</span>/500</span><button type="button" class="btn u-btn-primary" name="gpt_recom_btn" data-action="generate">${icon('Sparkles')} 생성하기</button></div></div></div><hr><div class="form-group"><div id="textarea_form${q.uid}"><label class="answer-label" for="t_body${q.uid}">자기소개서 내용</label><textarea class="answer-body form-control" id="t_body${q.uid}" data-q-field="body" placeholder="자기소개서 내용을 입력해 주세요." rows="8">${esc(q.body)}</textarea><div class="answer-footer"><div class="translation-tools" data-control-size="sm"><select aria-label="문항 ${index+1} 번역 언어" data-q-field="language" data-control-width="content">${['한국어','English','日本語','简体中文'].map(l=>`<option ${q.language===l?'selected':''}>${l}</option>`).join('')}</select><button type="button" data-action="translate">번역하기</button><button type="button" data-action="revert" ${q.original===null?'disabled':''} aria-label="문항 ${index+1} 번역 되돌리기">${icon('Undo2')}</button></div><div><span>글자수 <strong data-body-count>${q.body.length}</strong>자 <span>(공백포함)</span></span><button type="button" class="adjust-length" data-action="length">${icon('TextCursorInput')} 글자수 조정</button></div></div></div></div></div><div class="question-actions"><div><button type="button" name="up_btn" data-action="up" aria-label="문항 ${index+1} 위로" ${index===0?'disabled':''}>${icon('ArrowUp')}</button><button type="button" name="down_btn" data-action="down" aria-label="문항 ${index+1} 아래로" ${index===questions.length-1?'disabled':''}>${icon('ArrowDown')}</button><span class="separator"></span><button type="button" name="refresh_btn" data-action="reset" aria-label="문항 ${index+1} 초기화">${icon('RotateCcw')}</button>${index>0?`<button type="button" name="del_btn" data-action="delete" aria-label="문항 ${index+1} 삭제">${icon('Trash2')}</button>`:''}</div><button type="button" name="add_btn" data-action="add">${icon('Plus')} 문항 추가</button></div></form>`;}
function render(){$('#questions').innerHTML=questions.map(form).join('');}
function counts(el,q){el.querySelector('[data-body-count]').textContent=q.body.length;el.querySelector('[data-prompt-count]').textContent=q.prompt.length;}
$('#m_title').value=info.title;$('#m_title').addEventListener('input',e=>{info.title=e.target.value;persist();});summary(info);render();
$('#questions').addEventListener('submit',e=>e.preventDefault());
function update(e){const el=e.target.closest('[data-uid]');if(!el||!e.target.dataset.qField)return;const q=questions.find(x=>x.uid===+el.dataset.uid);q[e.target.dataset.qField]=e.target.value;counts(el,q);persist();}
$('#questions').addEventListener('input',update);$('#questions').addEventListener('change',update);
function confirmChange(title,message,action){modal(title,`<p>${message}</p>`,action);$('#dialog-confirm').textContent='변경하기';}
$('#questions').addEventListener('click',e=>{const b=e.target.closest('button'),el=b?.closest('[data-uid]');if(!el)return;const q=questions.find(x=>x.uid===+el.dataset.uid),index=questions.indexOf(q),finish=()=>{persist();render();};if(b.dataset.mode){q.mode=b.dataset.mode;el.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});el.querySelector('.ai-input').hidden=q.mode==='직접쓰기';persist();return;}switch(b.dataset.action){case 'add':{const next=blank();questions.splice(index+1,0,next);finish();$('#q_input'+next.uid).focus();$('#form'+next.uid).scrollIntoView({block:'start',behavior:'smooth'});break;}case 'up':case 'down':{const to=index+(b.dataset.action==='up'?-1:1);if(to<0||to>=questions.length)return;[questions[index],questions[to]]=[questions[to],questions[index]];finish();$('#form'+q.uid).scrollIntoView({block:'start',behavior:'smooth'});break;}case 'delete':confirmChange('이 문항을 삭제할까요?','현재 문항과 입력한 내용이 삭제됩니다.',()=>{questions.splice(index,1);finish();});break;case 'reset':confirmChange('이 문항을 초기화할까요?','질문, 키워드와 본문을 비웁니다.',()=>{questions[index]={...blank(),uid:q.uid};finish();});break;case 'generate':{if(!q.prompt.trim()){toast('나의 경험이나 키워드를 먼저 입력해 주세요.');$('#keyword_input'+q.uid).focus();return;}const apply=()=>{q.body=sampleAnswer;q.original=null;finish();toast('작성 결과를 본문에 적용했습니다.');};if(q.body.trim())confirmChange('본문을 새로 작성할까요?','새로 작성한 내용으로 기존 본문이 바뀝니다.',apply);else apply();break;}case 'translate':if(!q.body.trim()){toast('번역할 본문을 먼저 입력해 주세요.');return;}if(q.language==='한국어'){toast('번역할 언어를 선택해 주세요.');return;}if(q.language!=='English'){toast('선택한 언어로 번역할 수 없습니다. 다른 언어를 선택해 주세요.');return;}modal('번역 결과','<div class="example-title">I want to turn the difficulties users face into better experiences through thoughtful product design.</div><p>번역한 내용을 본문에 적용합니다. 번역 되돌리기로 이전 본문을 복원할 수 있습니다.</p>',()=>{q.original=q.body;q.body='I want to turn the difficulties users face into better experiences through thoughtful product design.';finish();});$('#dialog-confirm').textContent='적용하기';break;case 'revert':if(q.original!==null){q.body=q.original;q.original=null;finish();}break;case 'length':modal('글자수 조정','<label for="length-target">목표 글자수</label><input id="length-target" type="text" inputmode="numeric" pattern="[0-9]+" value="500" class="length-target">');break;}});
function preview(done=false){persist();modal(done?'작성 내용 확인':'자기소개서 미리보기',`<h3>${esc(info.title||'제목 없음')}</h3>${questions.map((q,i)=>`<h3>${i+1}. ${esc(q.question||q.type||'질문 없음')}</h3><div class="preview-answer">${esc(q.body||'입력한 내용이 없습니다.')}</div>`).join('')}`);}
$('#preview').addEventListener('click',()=>preview());for(const id of ['draft_btn','m_draft_btn'])$('#'+id).addEventListener('click',()=>{persist();toast('작성 내용을 임시저장했습니다.');});for(const id of ['submit_btn','m_submit_btn'])$('#'+id).addEventListener('click',()=>{if(!info.title.trim()){toast('자기소개서 제목을 입력해 주세요.');$('#m_title').focus();return;}const invalid=questions.find(q=>!q.type||!q.body.trim());if(invalid){toast('문항 카테고리와 자기소개서 내용을 입력해 주세요.');$('#form'+invalid.uid).scrollIntoView({block:'start',behavior:'smooth'});return;}preview(true);});
$('#advice_modal').addEventListener('click',()=>modal('AI 자기소개서 작성방법','<p>질문 카테고리와 질문을 정한 뒤, 나의 경험과 키워드를 입력합니다. 생성된 문장을 그대로 사용하기보다 실제 경험에 맞게 다듬어 주세요.</p><img class="example-image" src="./assets/writing-guide.png" alt="자기소개서 작성 안내">'));
